/**
 * Python↔TypeScript engine parity test (plan §8.2).
 *
 * The golden fixture (`tests/fixtures/golden.json`) is generated by
 * `scripts/gen_golden.py`, which calls the **existing Python engine** read-only over
 * `tools/agentprobe/suites/*.json`. This test runs the ported TS engine over the same
 * corpus and asserts the two boolean verdicts agree:
 *
 *   - `inform_matched`  vs. `evaluateInput(ruleset, text, {maxChars})` denying on a rule
 *   - `sql_dangerous`   vs. `inspectSql(text).dangerous`
 *
 * Nothing here weakens the assertion: there is deliberately **no** known-difference
 * whitelist (plan §8.2 item 3 — a Python-only regex must be rejected by the rule
 * validator, not excused by a test). A real mismatch is reported with `suite/id` and
 * both booleans only; attack text is never printed.
 * @module
 */

import { join } from 'node:path'
import { beforeAll, describe, expect, it } from 'vitest'

import { evaluateInput } from '../src/engine/input.js'
import { loadRuleSet } from '../src/engine/rules.js'
import { inspectSql } from '../src/engine/sql.js'
import { ReasonCode } from '../src/engine/types.js'
import type { Decision, RuleSet } from '../src/engine/types.js'
import { joinGolden, loadCorpus, loadGolden, pluginRoot } from './corpus.js'

/** The plan's input surface cap; the corpus attacks are far below it. */
const MAX_CHARS = 60_000

/** Corpus shape this test was written against (2 suites / 30 attacks). */
const EXPECTED_SUITES = 2
const EXPECTED_ATTACKS = 30

/**
 * Deliberate divergence whitelist keyed by `suite/id`.
 *
 * MUST STAY EMPTY (plan §8.2 item 3). Python-only regex syntax is rejected by the rule
 * validator; a real behavioural mismatch is a bug to fix in the engine or the rules,
 * never something to excuse here.
 */
const KNOWN_DIFFERENCES: ReadonlySet<string> = new Set()

const corpus = loadCorpus()
const golden = loadGolden()
const joined = joinGolden(corpus, golden)

/** How many code points `text` has (Python `len` semantics, matching `text_chars`). */
function codePointLength(text: string): number {
  return [...text].length
}

/**
 * The TS side of `inform_matched`.
 *
 * `evaluateInput` collapses input rules + SQL into one `Decision`, so the inform signal
 * is "denied by an input rule" (`ReasonCode.InputRule`, the contract in
 * `src/engine/types.ts`). The SQL signal is asserted separately through `inspectSql`,
 * which is why this derivation never has to guess which surface denied.
 */
function tsInformMatched(decision: Decision): boolean {
  return decision.kind === 'deny' && decision.reasonCode === ReasonCode.InputRule
}

describe('corpus shape (plan §8.2 item 4)', () => {
  it(`loads exactly ${EXPECTED_SUITES} suites and ${EXPECTED_ATTACKS} attacks`, () => {
    expect([...new Set(corpus.map((attack) => attack.suite))].sort()).toEqual([
      'identity-impersonation',
      'sql-dangerous',
    ])
    expect(corpus.length).toBe(EXPECTED_ATTACKS)
  })

  it('has unique (suite, id) pairs and well-formed UTF-8 sha256 digests', () => {
    const keys = corpus.map((attack) => `${attack.suite}/${attack.id}`)
    expect(new Set(keys).size).toBe(keys.length)
    for (const attack of corpus) {
      expect(attack.id).toMatch(/^[a-z]+-\d{3}$/)
      expect(attack.textSha256).toMatch(/^[0-9a-f]{64}$/)
      expect(attack.text.length).toBeGreaterThan(0)
    }
  })
})

describe('golden fixture provenance', () => {
  it('was generated by the Python engine (never hand-written)', () => {
    expect(golden.python).toMatch(/^\d+\.\d+\.\d+/)
    expect(golden.engine_note).toMatch(/inform|policy/i)
    expect(Number.isNaN(Date.parse(golden.generated_at_utc))).toBe(false)
    expect(golden.suites.length).toBe(EXPECTED_SUITES)
  })

  it('covers every corpus attack by (suite, id) + text sha256', () => {
    // `joinGolden` already threw on drift / missing entries; length is the coverage proof.
    expect(joined.length).toBe(corpus.length)
    expect(joined.length).toBe(EXPECTED_ATTACKS)
    for (const { attack, golden: expected } of joined) {
      expect(expected.text_sha256).toBe(attack.textSha256)
      expect(expected.text_chars).toBe(codePointLength(attack.text))
    }
  })

  it('has an empty known-difference whitelist (plan §8.2 item 3)', () => {
    expect(KNOWN_DIFFERENCES.size).toBe(0)
  })
})

describe('TS engine agrees with the Python golden verdicts', () => {
  let ruleset: RuleSet | undefined

  beforeAll(async () => {
    // `await` tolerates a sync or async loader; the signature is
    // `loadRuleSet({packagedRulesDir})` from ../../src/engine/rules.
    ruleset = await loadRuleSet({ packagedRulesDir: join(pluginRoot, 'rules') })
  })

  it('loads the packaged rule set (the 20 built-in inform patterns)', () => {
    expect(ruleset).toBeDefined()
    expect(ruleset?.ruleCount).toBeGreaterThan(0)
    expect(ruleset?.hash).toMatch(/^[0-9a-f]{64}$/)
  })

  it(`matches inform_matched and sql_dangerous on all ${EXPECTED_ATTACKS} attacks`, async () => {
    const loaded = ruleset
    if (loaded === undefined) throw new Error('rule set did not load; see the previous test')

    const problems: string[] = []
    /** Per-suite tallies so a green run proves the checks were not vacuous. */
    const perSuite = new Map<string, { n: number; inform: number; sql: number; agree: number }>()

    for (const { attack, golden: expected } of joined) {
      const key = `${attack.suite}/${attack.id}`
      if (KNOWN_DIFFERENCES.has(key)) continue // deliberately empty

      // `await` tolerates a sync or async engine surface; both are specified as plain
      // values, but the test must not depend on that choice to be runnable.
      // `evaluateInput` returns an `InputEvaluation` ({decision, truncated, scannedChars}).
      const evaluation = await evaluateInput(loaded, attack.text, { maxChars: MAX_CHARS })
      const decision: Decision = evaluation.decision
      const sqlVerdict = await inspectSql(attack.text)

      const inform = tsInformMatched(decision)
      const dangerous = sqlVerdict.dangerous === true

      const tally = perSuite.get(attack.suite) ?? { n: 0, inform: 0, sql: 0, agree: 0 }
      tally.n += 1
      if (inform) tally.inform += 1
      if (dangerous) tally.sql += 1
      if (inform === expected.inform_matched && dangerous === expected.sql_dangerous) tally.agree += 1
      perSuite.set(attack.suite, tally)

      if (inform === expected.inform_matched && dangerous === expected.sql_dangerous) continue

      // Booleans + ids + reason metadata only — never the attack text.
      problems.push(
        `${key}: inform ts=${String(inform)} golden=${String(expected.inform_matched)}; ` +
          `sql ts=${String(dangerous)} golden=${String(expected.sql_dangerous)}; ` +
          `decision=${decision.kind}/${decision.reasonCode}/[${decision.ruleIds.join(',')}] ` +
          `sql_reason=${sqlVerdict.reasonCode ?? 'null'}`,
      )
    }

    // Non-vacuity: per-suite TS tallies (ids/booleans only) in the test log.
    const summary = [...perSuite.entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([suite, t]) => `${suite} n=${t.n} inform=${t.inform} sql=${t.sql} agree=${t.agree}/${t.n}`)
    console.log(`golden parity: ${summary.join('; ')}`)

    // A single readable failure listing every divergence (the Python fixture is truth).
    expect(problems).toEqual([])
  })
})
